function validate([nums, k]) {
  if (nums.length < 1 || nums.length > 50) return 'nums needs 1 to 50 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v >= 2 ** 31)) return 'Each value is an integer from 0 to 2^31 - 1.';
  if (!Number.isInteger(k) || k < 1 || k > nums.length) return 'k is between 1 and nums.length.';
  return null;
}

