function findKOr(nums, k) {
  let result = 0;
  for (let bit = 0; bit < 31; bit++) {
    const mask = 1 << bit;
    let count = 0;
    for (const num of nums) {
      if ((num & mask) !== 0) {
        count++;
      }
    }
    if (count >= k) {
      result |= mask;
    }
  }
  return result;
}

