function findKOr(nums, k) {
  // Read each value's binary digits as text and tally them per position.
  const tally = new Array(32).fill(0);
  for (const value of nums) {
    const digits = value.toString(2).split('').reverse();
    digits.forEach((digit, position) => { if (digit === '1') tally[position] += 1; });
  }
  let answer = 0;
  tally.forEach((times, position) => { if (times >= k) answer += 2 ** position; });
  return answer;
}

