function generate(rand, size) {
  const n = size === 'large' ? 50 : 1 + Math.floor(rand() * 8);
  // Mix narrow and full-width values so both small and large K-ors appear.
  const widths = [2, 3, 4, 8, 31];
  const width = widths[Math.floor(rand() * widths.length)];
  const nums = Array.from({ length: n }, () => Math.floor(rand() * 2 ** width));
  const k = size === 'large' ? 1 + Math.floor(rand() * 30) : 1 + Math.floor(rand() * n);
  return [nums, k];
}
